# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id
proc validateDataColumnSidecar*(
    dag: ChainDAGRef, quarantine: ref Quarantine,
    dataColumnQuarantine: ref ColumnQuarantine,
    data_column_sidecar: fulu.DataColumnSidecar,
    wallTime: BeaconTime, subnet_id: uint64):
    Result[void, ValidationError] =

  template block_header: untyped = data_column_sidecar.signed_block_header.message
  # [REJECT] The sidecar is valid as verified by verify_data_column_sidecar(sidecar)
  block:
    let v = verify_data_column_sidecar(data_column_sidecar)
    if v.isErr:
      return dag.checkedReject(v.error)

  # [REJECT] The sidecar is for the correct subnet
  # -- i.e. `compute_subnet_for_data_column_sidecar(blob_sidecar.index) == subnet_id`.
  if not (compute_subnet_for_data_column_sidecar(data_column_sidecar.index) == subnet_id):
    return dag.checkedReject("DataColumnSidecar: The sidecar is not for the correct subnet")

  # [IGNORE] The sidecar is not from a future slot
  # (with a `MAXIMUM_GOSSIP_CLOCK_DISPARITY` allowance) -- i.e. validate that
  # `block_header.slot <= current_slot`(a client MAY queue future sidecars for
  # processing at the appropriate slot).
  if not (block_header.slot <=
      (wallTime + MAXIMUM_GOSSIP_CLOCK_DISPARITY).slotOrZero):
    return errIgnore("DataColumnSidecar: slot too high")

  # [IGNORE] The sidecar is from a slot greater than the latest
  # finalized slot -- i.e. validate that `block_header.slot >
  # compute_start_slot_at_epoch(state.finalized_checkpoint.epoch)`
  if not (block_header.slot > dag.finalizedHead.slot):
    return errIgnore("DataColumnSidecar: slot already finalized")

  # [IGNORE] The sidecar is the first sidecar for the tuple
  # (block_header.slot, block_header.proposer_index, data_column_sidecar.index)
  # with valid header signature, sidecar inclusion proof, and kzg proof.
  let block_root = hash_tree_root(block_header)
  if dataColumnQuarantine[].hasSidecar(
      block_root, block_header.slot, block_header.proposer_index, data_column_sidecar.index):
    return errIgnore("DataColumnSidecar: already have valid data column from same proposer")

  # [REJECT] The sidecar's `kzg_commitments` inclusion proof is valid as verified by
  # `verify_data_column_sidecar_inclusion_proof(sidecar)`.
  block:
    let v = check_data_column_sidecar_inclusion_proof(data_column_sidecar)
    if v.isErr:
      return dag.checkedReject(v.error)

  # [IGNORE] The sidecar's block's parent (defined by
  # `block_header.parent_root`) has been seen (via both gossip and
  # non-gossip sources) (a client MAY queue sidecars for processing
  # once the parent block is retrieved).
  #
  # [REJECT] The sidecar's block's parent (defined by
  # `block_header.parent_root`) passes validation.
  let parent = dag.getBlockRef(block_header.parent_root).valueOr:
    if block_header.parent_root in quarantine[].unviable:
      quarantine[].addUnviable(block_root)
      return dag.checkedReject("DataColumnSidecar: parent not validated")
    else:
      quarantine[].addMissing(block_header.parent_root)
      return errIgnore("DataColumnSidecar: parent not found")

  # [REJECT] The sidecar is from a higher slot than the sidecar's
  # block's parent (defined by `block_header.parent_root`).
  if not (block_header.slot > parent.bid.slot):
    return dag.checkedReject("DataColumnSidecar: slot lower than parents'")

  # [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's
  # block -- i.e. `get_checkpoint_block(store, block_header.parent_root,
  # store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root`.
  let
    finalized_checkpoint = getStateField(dag.headState, finalized_checkpoint)
    ancestor = get_ancestor(parent, finalized_checkpoint.epoch.start_slot)

  if ancestor.isNil:
    # This shouldn't happen: we should always be able to trace the parent back
    # to the finalized checkpoint (else it wouldn't be in the DAG)
    return errIgnore("DataColumnSidecar: Can't find ancestor")

  if not (
      finalized_checkpoint.root == ancestor.root or
      finalized_checkpoint.root.isZero):
    quarantine[].addUnviable(block_root)
    return dag.checkedReject(
      "DataColumnSidecar: Finalized checkpoint not an ancestor")

  # [REJECT] The sidecar is proposed by the expected `proposer_index`
  # for the block's slot in the context of the current shuffling
  # (defined by `block_header.parent_root`/`block_header.slot`).
  # If the proposer_index cannot immediately be verified against the expected
  # shuffling, the sidecar MAY be queued for later processing while proposers
  # for the block's branch are calculated -- in such a case do not
  # REJECT, instead IGNORE this message.
  let proposer = getProposer(dag, parent, block_header.slot).valueOr:
    warn "cannot compute proposer for data column"
    return errIgnore("DataColumnSidecar: Cannot compute proposer") # internal issue

  if uint64(proposer) != block_header.proposer_index:
    return dag.checkedReject("DataColumnSidecar: Unexpected proposer")

  # [REJECT] The proposer signature of `data_column_sidecar.signed_block_header`,
  # is valid with respect to the `block_header.proposer_index` pubkey.
  if not verify_block_signature(
      dag.forkAtEpoch(block_header.slot.epoch),
      getStateField(dag.headState, genesis_validators_root),
      block_header.slot,
      block_root,
      dag.validatorKey(proposer).get(),
      data_column_sidecar.signed_block_header.signature):
    return dag.checkedReject("DataColumnSidecar: Invalid proposer signature")

  # [REJECT] The sidecar's column data is valid as
  # verified by `verify_data_column_kzg_proofs(sidecar)`
  block:
    let r = check_data_column_sidecar_kzg_proofs(data_column_sidecar)
    if r.isErr:
      return dag.checkedReject(r.error)

  router.processor[].blockProcessor
template getCurrentBeaconTime(router: MessageRouter): BeaconTime =
  router.processor[].getCurrentBeaconTime()

type RouteBlockResult = Result[Opt[BlockRef], string]
proc routeSignedBeaconBlock*(
    router: ref MessageRouter, blck: ForkySignedBeaconBlock,
    blobsOpt: Opt[seq[BlobSidecar]], dataColumnsOpt: Opt[seq[fulu.DataColumnSidecar]],
    checkValidator: bool): Future[RouteBlockResult] {.async: (raises: [CancelledError]).} =
  ## Validate and broadcast beacon block, then add it to the block database
  ## Returns the new Head when block is added successfully to dag, none when
  ## block passes validation but is not added, and error otherwise
  let wallTime = router[].getCurrentBeaconTime()

  block:
    let vindex = ValidatorIndex(blck.message.proposer_index)
    if checkValidator and (vindex in router.processor.validatorPool[]):
      warn "A validator client attempts to send a block from " &
           "validator that is also manager by beacon node",
           validator_index = vindex
      return err("Block could not be sent from validator that is also " &
                 "managed by the beacon node")

  # Start with a quick gossip validation check such that broadcasting the
  # block doesn't get the node into trouble
  block:
    let res = validateBeaconBlock(
      router[].dag, router[].quarantine, blck, wallTime, {})

    if not res.isGoodForSending():
      warn "Block failed validation",
        blockRoot = shortLog(blck.root), blck = shortLog(blck.message),
        signature = shortLog(blck.signature), error = res.error()
      return err($(res.error()[1]))

    when typeof(blck).kind in [ConsensusFork.Deneb, ConsensusFork.Electra]:
      if blobsOpt.isSome:
        let blobs = blobsOpt.get()
        let kzgCommits = blck.message.body.blob_kzg_commitments.asSeq
        if blobs.len > 0 or kzgCommits.len > 0:
          let res = validate_blobs(
            kzgCommits,
            blobs.mapIt(KzgBlob(bytes: it.blob)),
            blobs.mapIt(it.kzg_proof))
          if res.isErr():
            warn "blobs failed validation",
              blockRoot = shortLog(blck.root),
              blobs = shortLog(blobs),
              blck = shortLog(blck.message),
              signature = shortLog(blck.signature),
              msg = res.error()
            return err(res.error())

  let
    sendTime = router[].getCurrentBeaconTime()
    delay = sendTime - blck.message.slot.block_deadline()
    # The block (and blobs, if present) passed basic gossip validation
    # - we can "safely" broadcast it now. In fact, per the spec, we
    # should broadcast it even if it later fails to apply to our
    # state.

  let res = await router[].network.broadcastBeaconBlock(blck)

  if res.isOk():
    beacon_blocks_sent.inc()
    beacon_blocks_sent_delay.observe(delay.toFloatSeconds())

    notice "Block sent",
      blockRoot = shortLog(blck.root), blck = shortLog(blck.message),
      signature = shortLog(blck.signature), delay
  else: # "no broadcast" is not a fatal error
    notice "Block not sent",
      blockRoot = shortLog(blck.root), blck = shortLog(blck.message),
      signature = shortLog(blck.signature), error = res.error()

  when typeof(blck).kind >= ConsensusFork.Fulu:
    var dataColumnRefs = Opt.none(fulu.DataColumnSidecars)
    let dataColumns = dataColumnsOpt.get()
    if dataColumnsOpt.isSome() and dataColumns.len != 0:
      var das_workers =
        newSeq[Future[SendResult]](len(dataColumns))
      for i in 0..<dataColumns.lenu64:
        let subnet_id =
          compute_subnet_for_data_column_sidecar(dataColumns[i].index)

        das_workers[i] =
          router[].network.broadcastDataColumnSidecar(subnet_id,
                                                      dataColumns[i])
      let allres = await allFinished(das_workers)
      for i in 0..<allres.len:
        let res = allres[i]
        doAssert res.finished()
        if res.failed():
          notice "Data column not sent",
            data_column = shortLog(dataColumns[i]), error = res.error[]
        else:
          notice "Data column sent",
            data_column = shortLog(dataColumns[i])
      # Push only those columns to processor for which we custody
      let
        metadata = router[].network.metadata.custody_group_count
        samples_per_slot = router[].network.cfg.SAMPLES_PER_SLOT
        custody_columns =
          router[].network.cfg.resolve_columns_from_custody_groups(
            router[].network.nodeId,
            max(samples_per_slot, metadata))

      var final_columns: seq[ref fulu.DataColumnSidecar]
      for dc in dataColumns:
        if dc.index in custody_columns:
          final_columns.add newClone(dc)
      dataColumnRefs = Opt.some(final_columns)
    let added = await router[].blockProcessor[].addBlock(
      MsgSource.api, ForkedSignedBeaconBlock.init(blck), dataColumnRefs)
  elif typeof(blck).kind in [ConsensusFork.Deneb, ConsensusFork.Electra]:
    var blobRefs = Opt.none(BlobSidecars)
    if blobsOpt.isSome():
      let blobs = blobsOpt.get()
      var workers = newSeq[Future[SendResult]](blobs.len)
      for i in 0..<blobs.lenu64:

  newProtocol(pk, enrIp, enrTcpPort, enrUdpPort, enrFields, bootstrapEnrs,
    bindPort = config.udpPort, bindIp = listenAddress,
    enrAutoUpdate = config.enrAutoUpdate, rng = rng)

func isCompatibleForkId*(discoveryForkId: ENRForkID, peerForkId: ENRForkID): bool =
  if discoveryForkId.fork_digest == peerForkId.fork_digest:
    if discoveryForkId.next_fork_version < peerForkId.next_fork_version:
      # Peer knows about a fork and we don't
      true
    elif discoveryForkId.next_fork_version == peerForkId.next_fork_version:
      # We should have the same next_fork_epoch
      discoveryForkId.next_fork_epoch == peerForkId.next_fork_epoch

    else:
      # Our next fork version is bigger than the peer's one
      false
  else:
    # Wrong fork digest
    false

proc queryRandom*(
    d: Eth2DiscoveryProtocol,
    forkId: ENRForkID,
    wantedAttnets: AttnetBits,
    wantedSyncnets: SyncnetBits,
    wantedCgcnets: CgcBits,
    minScore: int): Future[seq[Node]] {.async: (raises: [CancelledError]).} =
  ## Perform a discovery query for a random target
  ## (forkId) and matching at least one of the attestation subnets.

  let nodes = await d.queryRandom()

  var filtered: seq[(int, Node)]
  for n in nodes:
    var score: int = 0

    let
      eth2FieldBytes = n.record.get(enrForkIdField, seq[byte]).valueOr:
        continue
      peerForkId =
        try:
          SSZ.decode(eth2FieldBytes, ENRForkID)
        except SerializationError as e:
          debug "Could not decode the eth2 field of peer",
            peer = n.record.toURI(), exception = e.name, msg = e.msg
          continue

    if not forkId.isCompatibleForkId(peerForkId):
      continue

    let cgcCountBytes = n.record.get(enrCustodySubnetCountField, seq[byte])
    if cgcCountBytes.isOk():
      let cgcCountNode =
        try:
          SSZ.decode(cgcCountBytes.get(), uint8)
        except SerializationError as e:
          debug "Could not decode the cgc ENR field of peer",
            peer = n.record.toURI(), exception = e.name, msg = e.msg
          continue

    saturate(fromNow(node.beaconClock, nextProposalSlot)).toFloatSeconds()
  else:
    Inf)

sync_committee_active.set(if inCurrentSyncCommittee: 1 else: 0)

let epoch = slot.epoch
if epoch + 1 >= node.network.forkId.next_fork_epoch:
  # Update 1 epoch early to block non-fork-ready peers
  node.network.updateForkId(epoch, node.dag.genesis_validators_root)

# When we're not behind schedule, we'll speculatively update the clearance
# state in anticipation of receiving the next block - we do it after
# logging slot end since the nextActionWaitTime can be short
let advanceCutoff = node.beaconClock.fromNow(
  slot.start_beacon_time() + chronos.seconds(int(SECONDS_PER_SLOT - 1)))

