proc sendGetBlobsV2toSingleEl(
    connection: ELConnection,
    versioned_hashes: seq[engine_api.VersionedHash]
): Future[GetBlobsV2Response] {.async: (raises: [CatchableError]).} =
  let rpcClient = await connection.connectedRpcClient()

  ok()

func check_data_column_sidecar_inclusion_proof(
    data_column_sidecar: fulu.DataColumnSidecar): Result[void, ValidationError] =
  let res = data_column_sidecar.verify_data_column_sidecar_inclusion_proof()
  if res.isErr:
    return errReject(res.error)

  ok()

proc check_data_column_sidecar_kzg_proofs(
    data_column_sidecar: fulu.DataColumnSidecar): Result[void, ValidationError] =
  let res = data_column_sidecar.verify_data_column_sidecar_kzg_proofs()
  if res.isErr:
    return errReject(res.error)

if shouldGetBlob:
  let blobData =
    block:
      debug "Requesting blob sidecars from peer",
            slot = slot,
            peer = peer,
            peer_score = peer.getScore(),
            peer_speed = peer.netKbps(),
            topics = "syncman"
      let res = await blobSidecarsByRange(
        peer, slot, 1'u64, maxResponseItems = maxBlobsPerBlockElectra.Limit)
      if res.isErr():
        peer.updateScore(PeerScoreNoValues)
        return err(
          "Failed to receive blobs on request, reason: " & $res.error)
      res.get().asSeq()

  if len(blobData) == 0:
    peer.updateScore(PeerScoreNoValues)
    return err("An empty range of blobs was returned by peer")

